/** Discovery of a downloadable healthsites.io extract.
 *
 *  This is discovery in the sense experiment 39 settled: it resolves a location and yields a
 *  request, never bytes. healthsites.io sends no `access-control-allow-origin`, so the
 *  application cannot fetch it and a proxy is excluded by experiment 32's precedent. The
 *  practitioner's own browser performs the download, which CORS does not govern.
 *
 *  **The API key never becomes a value.** `download-evidence` serialises the whole run result
 *  into a shareable receipt, so a URL carrying the key would leak there. At run time this node
 *  only checks that the credential *resolves*; the URL is built at click time from the live
 *  session and discarded. See docs/experiments/30-local-credential-files.md. */
import type {AreaValue,Receipt,RemoteRequest} from './results.js';
import type {WorkflowNode} from './types.js';

export const HEALTHSITES_ORIGIN='https://healthsites.io';
export const HEALTHSITES_PROVIDER='healthsites';
export const HEALTHSITES_KINDS=['hospital','clinic','doctors','pharmacy','dentist','laboratory'] as const;

/** Resolves a secret for one credential reference, or throws. Supplied by the application so the
 *  session stays in the tab and out of the workflow. */
export type CredentialResolver=(ref:string,provider:string,origin:string)=>string;

export const ODBL_ATTRIBUTION='Health facility data \u00a9 healthsites.io contributors and \u00a9 OpenStreetMap contributors, under the Open Database License (ODbL). Redistributing a database derived from it obliges you to offer that under ODbL and to keep this attribution.';

const text=(value:unknown)=>typeof value==='string'?value.trim():'';

export function validateHealthsitesNode(node:WorkflowNode<'healthsites_discovery'>):void{
  if(!text(node.params.credentialRef))
    throw new Error('Name the credential to use for Healthsites discovery. Add it in the Credentials dialog first; this node stores the reference, never the key.');
  if(!text(node.params.country)&&!node.params.useArea)
    throw new Error('Choose a country, or connect a study area to bound the request.');
  const kinds=node.params.kinds||[];
  for(const kind of kinds)
    if(!(HEALTHSITES_KINDS as readonly string[]).includes(kind))
      throw new Error(`"${kind}" is not a healthsites facility kind.`);
}

/** The extent healthsites expects: a lon/lat box, comma separated. */
export function extentOf(area:AreaValue):string{
  const bounds=area.bounds;
  if(!bounds||bounds.length!==4||!bounds.every(Number.isFinite))
    throw new Error('The connected study area has no usable extent.');
  return bounds.map(v=>v.toFixed(5)).join(',');
}

export function healthsitesRequest(
  node:WorkflowNode<'healthsites_discovery'>, area:AreaValue|undefined, resolve:CredentialResolver,
):{value:{kind:'remote-request';rows:never[];centers:never[]};request:RemoteRequest;receipt:Receipt}{
  validateHealthsitesNode(node);
  const ref=text(node.params.credentialRef);
  // Check only. The secret is resolved again at click time and never stored, returned or logged.
  resolve(ref,HEALTHSITES_PROVIDER,HEALTHSITES_ORIGIN);
  if(node.params.useArea&&!area)
    throw new Error('Connect a study area, or choose a country instead.');
  const extent=node.params.useArea&&area?extentOf(area):null;
  const country=extent?'':text(node.params.country);
  const kinds=[...(node.params.kinds||[])];
  const query:Record<string,string>={page:'1'};
  if(extent)query.extent=extent; else query.country=country;

  const request:RemoteRequest={nodeId:node.id,provider:HEALTHSITES_PROVIDER,origin:HEALTHSITES_ORIGIN,
    credentialRef:ref,scope:extent?`study area ${extent}`:country,kinds,
    licence:'ODbL',attribution:ODBL_ATTRIBUTION,query};
  const activity=`<urn:fieldwork:run:${node.id}:healthsites>`;
  // The licence is an IRI rather than a label, so it resolves and can be compared. DCAT carries
  // the thing being requested; Dublin Core carries the terms that attach to it.
  const facts=`@prefix fw: <urn:fieldwork:>.\n@prefix prov: <http://www.w3.org/ns/prov#>.\n@prefix dcterms: <http://purl.org/dc/terms/>.\n@prefix dcat: <http://www.w3.org/ns/dcat#>.\n`
    +`${activity} a fw:RemoteAssetRequest, prov:Activity; `
    +`fw:requestOrigin <${HEALTHSITES_ORIGIN}>; `
    +`fw:credentialReference ${JSON.stringify(ref)}; `
    +(extent?`fw:requestExtent ${JSON.stringify(extent)}; `:`fw:requestCountry ${JSON.stringify(country)}; `)
    +`fw:requestedKinds ${JSON.stringify(kinds.join(', ')||'all')}; `
    +`prov:used <${HEALTHSITES_ORIGIN}#dataset>.\n`
    +`<${HEALTHSITES_ORIGIN}#dataset> a dcat:Dataset; `
    +`dcterms:title "healthsites.io health facilities"; `
    +`dcterms:license <https://opendatacommons.org/licenses/odbl/1-0/>; `
    +`dcterms:source <https://www.openstreetmap.org/copyright>; `
    +`dcterms:rights ${JSON.stringify(ODBL_ATTRIBUTION)}.\n`;
  return {value:{kind:'remote-request',rows:[],centers:[]},request,receipt:{nodeId:node.id,kind:'computation',facts,input:facts,rules:'',conclusions:[],
    method:'Resolved a download location and checked that the named credential is available. The licence and its obligations are presented at the moment of download, and the download proceeds only if the practitioner accepts them. Yields a request, never data: this prototype cannot fetch healthsites.io, which sends no cross-origin header, so your own browser performs the download. The key is never part of this result, and nothing here records what you downloaded or verifies that the file you later import is the file this described.'}};
}

/** Built at click time, in the dialog, from the live session. Never stored or returned to the
 *  workflow: the run receipt is shareable and the key must not reach it. */
export function healthsitesUrl(request:RemoteRequest,resolve:CredentialResolver):string{
  const secret=resolve(request.credentialRef,request.provider,request.origin);
  const url=new URL('/api/v3/facilities/',request.origin);
  for(const [key,value] of Object.entries(request.query))url.searchParams.set(key,value);
  url.searchParams.set('api-key',secret);
  return url.toString();
}
